    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    if a < 2:
        return False
    prime_factors = 0
    for i in range(2, int(sqrt(a)) + 1):
        if a % i == 0:
            if is_prime(i):
                prime_factors += 1
            if a // i != i and is_prime(a // i):
